import { createReactEmailTheme } from "@/components/email/create-react-email-theme";
import { notionTheme as notionThemeTokens } from "@/components/email/theme-notion-tokens";

export const NotionTailwindConfig = createReactEmailTheme(notionThemeTokens);

export const notionTheme = NotionTailwindConfig;

import type { TailwindConfig } from "react-email";
import plugin from "tailwindcss/plugin";

import type { EmailThemeTokens } from "@/components/email/email-theme-types";

const fontScale = {
  "11": {
    fontSize: "11px",
    fontWeight: "400",
    letterSpacing: "-0.033px",
    lineHeight: "1.5",
  },
  "13": {
    fontSize: "13px",
    fontWeight: "400",
    letterSpacing: "-0.039px",
    lineHeight: "1.5",
  },
  "14": { fontSize: "14px", lineHeight: "1.5" },
  "16": {
    fontSize: "16px",
    fontWeight: "400",
    letterSpacing: "-0.048px",
    lineHeight: "1.5",
  },
  "20": {
    fontSize: "20px",
    fontWeight: "500",
    letterSpacing: "-0.1px",
    lineHeight: "1.2",
  },
  "24": {
    fontSize: "24px",
    fontWeight: "600",
    letterSpacing: "-0.084px",
    lineHeight: "1",
  },
  "28": {
    fontSize: "28px",
    fontWeight: "600",
    letterSpacing: "-0.084px",
    lineHeight: "1.3",
  },
} as const;

const emailUtilitiesPlugin = plugin(({ addUtilities, addVariant }) => {
  addVariant("mobile", "@media (max-width: 600px)");

  const utilities: Record<string, Record<string, string>> = {};
  for (const [step, token] of Object.entries(fontScale)) {
    utilities[`.font-${step}`] = token;
  }
  addUtilities(utilities);
});

export const createReactEmailTheme = (
  theme: EmailThemeTokens
): TailwindConfig => ({
  plugins: [emailUtilitiesPlugin],
  theme: {
    extend: {
      colors: {
        bg: theme.colorBackground,
        "bg-2": theme.colorBackgroundMuted,
        brand: theme.colorPrimary,
        fg: theme.colorText,
        "fg-2": theme.colorTextMuted,
        "fg-3": theme.colorTextSubtle,
        stroke: theme.colorBorder,
        "stroke-strong": theme.colorBorderSubtle,
      },
      fontFamily: {
        mono: [theme.fontFamilyMono],
        sans: [theme.fontFamily],
      },
    },
  },
});

export interface EmailThemeTokens {
  borderRadius: string;
  borderRadiusLg: string;
  button: {
    primary: {
      backgroundColor: string;
      borderRadius: string;
      color: string;
      fontSize: string;
      fontWeight: string;
      paddingX: string;
      paddingY: string;
    };
    secondary: {
      backgroundColor: string;
      border: string;
      borderRadius: string;
      color: string;
      fontSize: string;
      fontWeight: string;
      paddingX: string;
      paddingY: string;
    };
  };
  colorBackground: string;
  colorBackgroundMuted: string;
  colorBackgroundSubtle: string;
  colorBorder: string;
  colorBorderSubtle: string;
  colorDanger: string;
  colorPrimary: string;
  colorPrimaryForeground: string;
  colorPrimaryHover: string;
  colorSuccess: string;
  colorText: string;
  colorTextMuted: string;
  colorTextSubtle: string;
  colorWarning: string;
  containerWidth: string;
  fontFamily: string;
  fontFamilyMono: string;
  fontSizeBase: string;
  fontSizeHeading: string;
  fontSizeLg: string;
  fontSizeSm: string;
  fontSizeXl: string;
  fontWeightBold: string;
  fontWeightMedium: string;
  fontWeightNormal: string;
  lineHeightBase: string;
  spacingBase: string;
  spacingLg: string;
  spacingXl: string;
}
